ONBOARDING_DAY2_BOSS_RATING = f"<b>{SYS} // ОБЩИЙ РЕЙД</b>\n\nКаждую неделю игроки сражаются с общим боссом — любой XP наносит ему урон, а топ-участники получают бонус.\n/boss — состояние рейда\n/rating — кто впереди"
ONBOARDING_STOPPED = "Подсказки отключены. Основные протоколы доступны через /help"
STREAK_DANGER = f"<b>{SYS} // УГРОЗА СЕРИИ</b>\n\nДо конца дня осталось меньше двух часов.\nНевыполненных квестов: <b>{{pending}}</b>\nТвоя серия <b>{{streak}}</b> дн. будет обнулена, а HP — снижено.\nARISE не повторяет дважды. /quests"
BOSS_LOW_HP = f"<b>{SYS} // БОСС ПРИ СМЕРТИ</b>\n\n<b>{{name}}</b> держится из последних сил: осталось <b>{{hp}} HP</b> ⟨{{pct}}%⟩.\nЛюбой XP наносит ему урон.\nДобей его до воскресенья — награда всем участникам. /boss"
WINBACK = f"<b>{SYS} // ПРОТОКОЛ ВОЗВРАЩЕНИЯ</b>\n\nТы не выходил на связь <b>{{days}}</b> дн.\nARISE фиксирует уклонение. Вернись сегодня — и получишь <b>+{{bonus}} XP</b>.\nТвой прогресс ждёт: уровень <b>{{level}}</b>, ранг <b>{{rank}}</b>. /quests"
WINBACK_BONUS_GRANTED = f"<b>{SYS} // КОНТРАКТ ВОЗОБНОВЛЁН</b>\n\nВозвращение зафиксировано. Начислено: <b>+{{bonus}} XP</b>.\nБольше не исчезай."
STREAK_MILESTONE = f"<b>{SYS} // ВЕХА СЕРИИ</b>\n\nСерия достигла <b>{{streak}}</b> дней подряд. 🔥\nНаграда: <b>+{{bonus}} XP</b>{{freeze_line}}\n\nARISE признаёт твою дисциплину."
STREAK_MILESTONE_FREEZE = "\nПодарок: <b>заморозка серии x{count}</b> 🧊"
GATE_OPENED = f"<b>{SYS} // ОБНАРУЖЕНА АНОМАЛИЯ</b>\n\nСегодня перед тобой открылась аномалия:\n⛩ <b>{{title}}</b>\n\nПовышенная награда. Повышенный риск для твоей лени.\nОкно закроется в полночь. /quests"
GEMINI_DISCLAIMER = f"<b>{SYS} // УВЕДОМЛЕНИЕ ОБ АНАЛИЗЕ</b>\n\nТекст отчёта передаётся во внешний аналитический модуль <b>Google Gemini API</b> для оценки. Твой Telegram ID вместе с текстом не передаётся.\n\nНе пиши то, что не готов доверить внешнему сервису.\n<i>Подробнее: <a href=\"{{privacy_url}}\">политика конфиденциальности</a></i>"
DELETE_ME_CONFIRM = f"<b>{SYS} // ЗАПРОС НА СТИРАНИЕ</b>\n\nТы требуешь удалить себя из реестра игроков.\n\nБудет безвозвратно удалено: профиль, прогресс, квесты, отчёты, достижения и урон боссу недели.\nЗаписи о платежах сохранятся в обезличенном виде.\n\n<b>Действие необратимо.</b> Подтверди в течение 5 минут."
DELETE_ME_DONE = f"<b>{SYS}</b>\n\nЗапись об игроке стёрта. ARISE тебя не помнит.\nЕсли решишь вернуться — /start начнёт всё с ранга E."
DELETE_ME_CANCELLED = f"<b>{SYS}</b>\n\nСтирание отменено. Реестр сохранён."
DELETE_ME_EXPIRED = f"<b>{SYS}</b>\n\nЗапрос устарел. Повтори /delete_me, если решение в силе."
